```java
// ==================== ENTITIES ====================

package com.carrental.entity;

import jakarta.persistence.*;
import lombok.*;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Set;

// ---------- BASE ENTITY ----------
@MappedSuperclass
@Getter @Setter
public abstract class BaseEntity {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @CreationTimestamp
    @Column(updatable = false)
    private LocalDateTime createdAt;

    @UpdateTimestamp
    private LocalDateTime updatedAt;
}

// ---------- USER ----------
@Entity
@Table(name = "users")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class User extends BaseEntity {

    @Column(nullable = false, unique = true)
    private String email;

    @Column(nullable = false)
    private String password;

    @Column(nullable = false)
    private String firstName;

    @Column(nullable = false)
    private String lastName;

    private String phone;

    @Enumerated(EnumType.STRING)
    private UserRole role;

    private boolean enabled = true;

    @OneOne(mappedBy = "user", cascade = CascadeType.ALL)
    private Customer customerProfile;
}

// ---------- CUSTOMER ----------
@Entity
@Table(name = "customers")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Customer extends BaseEntity {

    @OneToOne
    @JoinColumn(name = "user_id", nullable = false)
    private User user;

    @Column(nullable = false)
    private String driverLicenseNumber;

    @Column(nullable = false)
    private LocalDate driverLicenseExpiry;

    private String driverLicenseCountry;

    private LocalDate dateOfBirth;

    @Embedded
    private Address address;

    private String emergencyContactName;
    private String emergencyContactPhone;

    private int loyaltyPoints = 0;

    @OneToMany(mappedBy = "customer")
    private List<Reservation> reservations;

    @OneToMany(mappedBy = "customer")
    private List<Rental> rentals;
}

// ---------- ADDRESS (EMBEDDABLE) ----------
@Embeddable
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Address {
    private String street;
    private String city;
    private String state;
    private String zipCode;
    private String country;
}

// ---------- LOCATION ----------
@Entity
@Table(name = "locations")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Location extends BaseEntity {

    @Column(nullable = false)
    private String name;

    @Column(nullable = false, unique = true)
    private String code;

    @Embedded
    private Address address;

    private String phone;
    private String email;

    private Double latitude;
    private Double longitude;

    private String openingHours; // JSON string o stringa formattata

    private boolean airport;
    private boolean active = true;

    @OneToMany(mappedBy = "currentLocation")
    private List<Vehicle> vehicles;
}

// ---------- VEHICLE ----------
@Entity
@Table(name = "vehicles")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Vehicle extends BaseEntity {

    @Column(nullable = false, unique = true)
    private String licensePlate;

    @Column(nullable = false)
    private String brand;

    @Column(nullable = false)
    private String model;

    private int year;
    private String color;

    @Column(unique = true)
    private String vin; // Vehicle Identification Number

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private VehicleCategory category;

    @Enumerated(EnumType.STRING)
    private TransmissionType transmission;

    @Enumerated(EnumType.STRING)
    private FuelType fuelType;

    private int seats;
    private int doors;
    private boolean airConditioning;
    private boolean gps;
    private int trunkCapacityLiters;

    private long mileage;

    @Column(nullable = false, precision = 10, scale = 2)
    private BigDecimal dailyRate;

    @Column(precision = 10, scale = 2)
    private BigDecimal weeklyRate;

    @Column(precision = 10, scale = 2)
    private BigDecimal monthlyRate;

    @Column(precision = 10, scale = 2)
    private BigDecimal depositAmount;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private VehicleStatus status;

    @ManyToOne
    @JoinColumn(name = "current_location_id")
    private Location currentLocation;

    @ElementCollection
    @CollectionTable(name = "vehicle_images", joinColumns = @JoinColumn(name = "vehicle_id"))
    @Column(name = "image_url")
    private List<String> imageUrls;

    private LocalDate insuranceExpiry;
    private LocalDate lastServiceDate;
    private LocalDate nextServiceDue;
}

// ---------- RESERVATION ----------
@Entity
@Table(name = "reservations")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Reservation extends BaseEntity {

    @Column(nullable = false, unique = true)
    private String reservationCode;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "customer_id", nullable = false)
    private Customer customer;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "vehicle_id")
    private Vehicle vehicle;

    @Enumerated(EnumType.STRING)
    private VehicleCategory requestedCategory;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "pickup_location_id", nullable = false)
    private Location pickupLocation;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "dropoff_location_id", nullable = false)
    private Location dropoffLocation;

    @Column(nullable = false)
    private LocalDateTime pickupDateTime;

    @Column(nullable = false)
    private LocalDateTime dropoffDateTime;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private ReservationStatus status;

    @Column(precision = 10, scale = 2)
    private BigDecimal estimatedTotal;

    @Column(precision = 10, scale = 2)
    private BigDecimal depositPaid;

    @ManyToMany
    @JoinTable(
        name = "reservation_extras",
        joinColumns = @JoinColumn(name = "reservation_id"),
        inverseJoinColumns = @JoinColumn(name = "extra_id")
    )
    private Set<Extra> extras;

    private String notes;
    private LocalDateTime cancelledAt;
    private String cancellationReason;
}

// ---------- RENTAL ----------
@Entity
@Table(name = "rentals")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Rental extends BaseEntity {

    @Column(nullable = false, unique = true)
    private String rentalCode;

    @OneToOne
    @JoinColumn(name = "reservation_id")
    private Reservation reservation;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "customer_id", nullable = false)
    private Customer customer;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "vehicle_id", nullable = false)
    private Vehicle vehicle;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "pickup_location_id", nullable = false)
    private Location pickupLocation;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "dropoff_location_id")
    private Location actualDropoffLocation;

    @Column(nullable = false)
    private LocalDateTime pickupDateTime;

    private LocalDateTime expectedReturnDateTime;
    private LocalDateTime actualReturnDateTime;

    private long pickupMileage;
    private Long returnMileage;

    private String pickupFuelLevel;
    private String returnFuelLevel;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private RentalStatus status;

    @Column(precision = 10, scale = 2)
    private BigDecimal baseAmount;

    @Column(precision = 10, scale = 2)
    private BigDecimal extrasAmount;

    @Column(precision = 10, scale = 2)
    private BigDecimal lateFee;

    @Column(precision = 10, scale = 2)
    private BigDecimal damageFee;

    @Column(precision = 10, scale = 2)
    private BigDecimal fuelCharge;

    @Column(precision = 10, scale = 2)
    private BigDecimal totalAmount;

    @Column(precision = 10, scale = 2)
    private BigDecimal depositAmount;

    @ManyToMany
    @JoinTable(
        name = "rental_extras",
        joinColumns = @JoinColumn(name = "rental_id"),
        inverseJoinColumns = @JoinColumn(name = "extra_id")
    )
    private Set<Extra> extras;

    private String pickupNotes;
    private String returnNotes;
    private String damageReport;

    @OneToMany(mappedBy = "rental", cascade = CascadeType.ALL)
    private List<Payment> payments;
}

// ---------- EXTRA ----------
@Entity
@Table(name = "extras")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Extra extends BaseEntity {

    @Column(nullable = false)
    private String name;

    private String description;

    @Column(nullable = false, precision = 10, scale = 2)
    private BigDecimal dailyRate;

    @Column(precision = 10, scale = 2)
    private BigDecimal flatRate;

    private boolean perDay; // true = daily rate, false = flat rate
    private boolean active = true;
}

// ---------- PAYMENT ----------
@Entity
@Table(name = "payments")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Payment extends BaseEntity {

    @Column(nullable = false, unique = true)
    private String transactionId;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "rental_id", nullable = false)
    private Rental rental;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "customer_id", nullable = false)
    private Customer customer;

    @Column(nullable = false, precision = 10, scale = 2)
    private BigDecimal amount;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private PaymentMethod paymentMethod;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private PaymentStatus status;

    private String description;
    private String stripePaymentIntentId;
    private String receiptUrl;

    private LocalDateTime paidAt;
    private LocalDateTime refundedAt;

    @Column(precision = 10, scale = 2)
    private BigDecimal refundAmount;
}

// ---------- REVIEW ----------
@Entity
@Table(name = "reviews")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Review extends BaseEntity {

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "rental_id", nullable = false)
    private Rental rental;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "customer_id", nullable = false)
    private Customer customer;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "vehicle_id", nullable = false)
    private Vehicle vehicle;

    @Column(nullable = false)
    private int rating; // 1-5

    private String title;

    @Column(length = 2000)
    private String comment;

    private int cleanlinessRating;
    private int comfortRating;
    private int valueForMoneyRating;

    private boolean verified = false;
    private boolean visible = true;
}

// ---------- DAMAGE REPORT ----------
@Entity
@Table(name = "damage_reports")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class DamageReport extends BaseEntity {

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "rental_id", nullable = false)
    private Rental rental;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "vehicle_id", nullable = false)
    private Vehicle vehicle;

    @Column(nullable = false)
    private String description;

    private String location; // area del veicolo

    @Column(precision = 10, scale = 2)
    private BigDecimal estimatedRepairCost;

    @ElementCollection
    @CollectionTable(name = "damage_photos", joinColumns = @JoinColumn(name = "damage_report_id"))
    @Column(name = "photo_url")
    private List<String> photoUrls;

    private boolean resolved = false;
    private LocalDateTime resolvedAt;
}
```

